package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.assetmetadata.*;
import cn.mop.domain.assetmetadata.ManualAssetMetadataRepository.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class AssetDateQueryControllerTest {
    static final String ACTOR="58000000-0000-4000-8000-000000000001",TENANT="58000000-0000-4000-8000-000000000011";static final LocalDate DAY=LocalDate.of(2026,10,3);static final Instant NOW=Instant.parse("2026-10-02T16:00:00Z");
    PlatformRepository platform;ManualAssetMetadataRepository metadata;AssetDateQueryController controller;
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);metadata=mock(ManualAssetMetadataRepository.class);controller=new AssetDateQueryController(platform,metadata,Clock.fixed(NOW,ZoneOffset.UTC));when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"msp",7,true)));}
    MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/api/v1/assets/date-assessments");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","synthetic-trace");r.addParameter("date_field","warranty_expiry");r.addParameter("window","WITHIN_30_DAYS");return r;}
    Access access(){return new Access(ACTOR,TENANT,7,"synthetic-trace");}
    Current row(int n){String id=String.format("58000000-0000-4000-8000-%012d",100+n);Asset a=new Asset(id,TENANT,"synthetic-"+n,"router","192.0.2.1","site-a","unknown","DRAFT","manual",null,"NOT_ONBOARDED",2,NOW.minusSeconds(n+100),NOW,"UNKNOWN","PENDING_ONBOARDING");var m=new ManualAssetMetadata(a.name(),a.type(),a.siteId(),null,null,null,null,null,null,null,DAY.plusDays(29),null,null,"synthetic");return new Current(new Snapshot(a,m,2L),ACTOR,NOW,List.of());}
    Map<?,?> data(MockHttpServletRequest r){return (Map<?,?>)((Map<?,?>)controller.search(r)).get("data");}
    @Test void boundedPageUsesServerDateAndCompleteThreePartCursor(){List<Current> rows=new ArrayList<>();for(int i=0;i<11;i++)rows.add(row(i));var r=request();r.addParameter("page_size","10");when(metadata.searchDates(access(),ManualAssetFilter.fromQuery(Map.of()),new AssetDateFilter(AssetDateFilter.Field.WARRANTY_EXPIRY,AssetDateFilter.Window.WITHIN_30_DAYS,DAY),11,null,null)).thenReturn(rows);var result=data(r);assertEquals(10,((List<?>)result.get("items")).size());assertEquals(true,result.get("has_more"));assertEquals(rows.get(9).snapshot().asset().id(),result.get("next_before_id"));assertEquals(DAY,result.get("next_expected_reference_date"));assertEquals(NOW,result.get("observed_at"));assertEquals("NOT_FROZEN_ACROSS_PAGES",result.get("metadata_change_semantics"));verify(platform).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void emptyPageIsExplicitAndHasNoCursor(){when(metadata.searchDates(any(),any(),any(),anyInt(),any(),any())).thenReturn(List.of());var result=data(request());assertEquals(false,result.get("has_more"));for(String key:List.of("next_before_id","next_before_created_at","next_expected_reference_date"))assertNull(result.get(key));assertEquals(List.of(),result.get("items"));}
    @Test void cursorReferenceDayCannotOverrideServerDay(){var r=request();r.addParameter("before_created_at",NOW.toString());r.addParameter("before_id",row(1).snapshot().asset().id());r.addParameter("expected_reference_date","2026-10-02");var error=assertThrows(DomainException.class,()->data(r));assertEquals(409,error.status);assertEquals("DATE_REFERENCE_CHANGED",error.code);verifyNoInteractions(metadata);}
    @Test void validCursorAndLiteralTextAreForwardedWithoutScopeOverride(){var r=request();r.addParameter("before_created_at",NOW.toString());String id=row(1).snapshot().asset().id();r.addParameter("before_id",id);r.addParameter("expected_reference_date",DAY.toString());r.addParameter("name","LITERAL%_Ä");r.addParameter("site_id","site-a");when(metadata.searchDates(any(),any(),any(),anyInt(),any(),any())).thenReturn(List.of());data(r);verify(metadata).searchDates(access(),ManualAssetFilter.fromQuery(Map.of("name","LITERAL%_Ä","site_id","site-a")),new AssetDateFilter(AssetDateFilter.Field.WARRANTY_EXPIRY,AssetDateFilter.Window.WITHIN_30_DAYS,DAY),16,NOW,id);}
    @Test void duplicateUnknownUnpairedAndInvalidQueriesFailBeforeReading(){for(String key:List.of("as_of_date","tenant_id","timezone","unexpected")){var r=request();r.addParameter(key,"x");assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);}var duplicate=request();duplicate.addParameter("window","PAST_DATE");assertEquals(400,assertThrows(DomainException.class,()->data(duplicate)).status);for(String key:List.of("before_id","before_created_at","expected_reference_date")){var r=request();r.addParameter(key,"x");assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);}var invalid=request();invalid.setParameter("page_size","101");assertEquals(400,assertThrows(DomainException.class,()->data(invalid)).status);verifyNoInteractions(metadata);}
    @Test void fieldAndWindowMandatoryAndStrict(){for(String key:List.of("date_field","window")){var r=request();r.removeParameter(key);assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);r.setParameter(key,"forged");assertEquals(400,assertThrows(DomainException.class,()->data(r)).status);}verifyNoInteractions(metadata);}
    @Test void customerAndStaleSessionsCannotQuery(){for(String role:List.of("viewer","tadmin","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));assertEquals(403,assertThrows(DomainException.class,()->data(request())).status);}when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"msp",0,true)));assertEquals(401,assertThrows(DomainException.class,()->data(request())).status);verifyNoInteractions(metadata);}
    @Test void unknownWindowCanProjectAbsenceWithoutDateInference(){var a=row(1).snapshot().asset();var current=new Current(new Snapshot(a,null,null),null,null,List.of());when(metadata.searchDates(any(),any(),any(),anyInt(),any(),any())).thenReturn(List.of(current));var r=request();r.setParameter("window","UNKNOWN");var result=data(r);var item=(Map<?,?>)((List<?>)result.get("items")).get(0);var assessment=(Map<?,?>)item.get("assessment");assertNull(assessment.get("metadata_version"));assertEquals("UNKNOWN",((Map<?,?>)assessment.get("warranty_expiry")).get("position"));}
    @Test void unexpectedRepositoryWindowMismatchFailsClosed(){when(metadata.searchDates(any(),any(),any(),anyInt(),any(),any())).thenReturn(List.of(row(1)));var r=request();r.setParameter("window","PAST_DATE");assertThrows(IllegalStateException.class,()->data(r));}
}
